using System.Collections;
using System.Reflection;
using UnityEditor.SceneManagement;
using UnityEngine.TestTools;
using NUnit.Framework;
using UnityEngine;
namespace SpatialSurvivor.Tests {
public class SurvivorEnemyCrowdTests {
 GameObject root;RoomNavigation nav;Vector3 center=new Vector3(100,0,100);SurvivorGame.Enemy[] crowd;
 [SetUp]public void Setup(){root=new GameObject("Crowd fixture");var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.SetParent(root.transform);floor.layer=RoomNavigation.Layer;floor.transform.position=center-Vector3.up*.1f;floor.transform.localScale=new Vector3(10,.2f,10);Physics.SyncTransforms();nav=new RoomNavigation();nav.Rebuild(center+Vector3.up*1.65f);crowd=new SurvivorGame.Enemy[18];for(int i=0;i<crowd.Length;i++){var go=new GameObject("Creature "+i);go.transform.SetParent(root.transform);crowd[i]=new SurvivorGame.Enemy{go=go,type=i%4,radius=new[]{.1f,.1f,.21f,.135f}[i%4],y=0};}}
 [TearDown]public void Cleanup(){Object.DestroyImmediate(root);}
 void At(int i,Vector3 offset){crowd[i].active=true;crowd[i].go.transform.position=center+offset;}
 void CheckGaps(float tolerance=.01f){for(int i=0;i<crowd.Length;i++)if(crowd[i].active)for(int j=i+1;j<crowd.Length;j++)if(crowd[j].active)Assert.That(SurvivorGame.Distance(crowd[i].go.transform.position,crowd[j].go.transform.position),Is.GreaterThanOrEqualTo(SurvivorEnemyCrowd.Radius(crowd[i])+SurvivorEnemyCrowd.Radius(crowd[j])+.035f-tolerance),"Pair "+i+" / "+j);}
 [Test]public void EighteenPursuersKeepMovingAndBodySpaceAroundStationaryPlayer(){for(int i=0;i<18;i++){float a=i*Mathf.PI*2/18;At(i,new Vector3(Mathf.Cos(a)*3.5f,0,Mathf.Sin(a)*3.5f));}var travel=new float[18];for(int f=0;f<700;f++){for(int i=0;i<18;i++){var e=crowd[i];var before=e.go.transform.position;e.go.transform.position=SurvivorEnemyCrowd.Move(i,crowd,SurvivorEnemyCrowd.PursuitGoal(i,crowd,center,nav),.015f,nav);if(f>=520)travel[i]+=SurvivorGame.Distance(before,e.go.transform.position);}SurvivorEnemyCrowd.Resolve(crowd,nav,1/90f);}CheckGaps();int near=0;for(int i=0;i<18;i++){var e=crowd[i];if(SurvivorGame.Distance(e.go.transform.position,center)<1.8f)near++;Assert.That(nav.Contains(e.go.transform.position,e.radius),Is.True);Assert.That(travel[i],Is.GreaterThan(.35f),"Crowded creature must keep moving: "+i);}Assert.That(near,Is.GreaterThan(5),"Avoidance must still let creatures approach and attack");}
 [Test]public void ExactCoincidenceRecoversWithoutRandomNaNs(){At(0,Vector3.zero);At(1,Vector3.zero);for(int i=0;i<90;i++)SurvivorEnemyCrowd.Resolve(crowd,nav,1/90f);CheckGaps();Assert.That(float.IsNaN(crowd[0].go.transform.position.x),Is.False);}
 [Test]public void FrozenCreatureRemainsStillWhileNeighborStepsAway(){At(0,Vector3.zero);At(1,Vector3.right*.1f);crowd[0].freeze=2;var frozen=crowd[0].go.transform.position;for(int i=0;i<60;i++)SurvivorEnemyCrowd.Resolve(crowd,nav,1/90f);Assert.That(crowd[0].go.transform.position,Is.EqualTo(frozen));CheckGaps();}
 [Test]public void FastMovementCannotTunnelThroughCreature(){At(0,Vector3.left);At(1,Vector3.zero);var p=SurvivorEnemyCrowd.Move(0,crowd,center+Vector3.right,2,nav);Assert.That(SurvivorGame.Distance(p,crowd[1].go.transform.position),Is.GreaterThanOrEqualTo(SurvivorEnemyCrowd.Radius(crowd[0])+SurvivorEnemyCrowd.Radius(crowd[1])+.034f));Assert.That(nav.Contains(p,crowd[0].radius),Is.True);}
 [Test]public void BlockedApproachDetoursAroundStationaryPeer(){At(0,Vector3.left);At(1,Vector3.zero);crowd[1].freeze=10;float travel=0;for(int f=0;f<180;f++){var before=crowd[0].go.transform.position;crowd[0].go.transform.position=SurvivorEnemyCrowd.Move(0,crowd,center+Vector3.right,.015f,nav);travel+=SurvivorGame.Distance(before,crowd[0].go.transform.position);CheckGaps();}Assert.That(crowd[0].go.transform.position.x,Is.GreaterThan(center.x+.5f),"Creature must pass the peer, not wait behind it");Assert.That(travel,Is.GreaterThan(1.8f));}
 [Test]public void SpawnReservesLandingSpaceAndDyingBodies(){At(0,Vector3.zero);crowd[0].falling=true;Assert.That(SurvivorEnemyCrowd.SpawnClear(center,1,crowd[1],crowd),Is.False);crowd[0].active=false;crowd[0].deathRemaining=.3f;Assert.That(SurvivorEnemyCrowd.SpawnClear(center,1,crowd[1],crowd),Is.False);crowd[0].deathRemaining=0;Assert.That(SurvivorEnemyCrowd.SpawnClear(center,1,crowd[1],crowd),Is.True);}
 [Test]public void CrowdedBoundarySkipsOccupiedSpawnAndFullRoomDefers(){Assert.That(nav.Spawn(center,2,.1f,new System.Random(0),out var first,out _),Is.True);At(0,first-center);Assert.That(nav.Spawn(center,2,.1f,new System.Random(0),out var second,out _,false,p=>SurvivorEnemyCrowd.SpawnClear(p,1,crowd[1],crowd)),Is.True);Assert.That(SurvivorGame.Distance(first,second),Is.GreaterThan(.4f));Assert.That(nav.Spawn(center,2,.1f,new System.Random(0),out _,out _,false,p=>false),Is.False);}
 [Test]public void WallPreventsSeparationFromPushingIntoFurniture(){var box=GameObject.CreatePrimitive(PrimitiveType.Cube);box.layer=RoomNavigation.Layer;box.transform.SetParent(root.transform);box.transform.position=center+new Vector3(.75f,.6f,0);box.transform.localScale=new Vector3(.6f,1.2f,2);Physics.SyncTransforms();nav.Rebuild(center+Vector3.up*1.65f);At(0,Vector3.zero);At(1,Vector3.left*.1f);for(int i=0;i<90;i++)SurvivorEnemyCrowd.Resolve(crowd,nav,1/90f);foreach(var e in crowd)if(e.active)Assert.That(nav.Contains(e.go.transform.position,e.radius),Is.True);CheckGaps();}
 [UnityTest]public IEnumerator CombatStepKeepsFullMixedWaveSeparatedAfterLanding(){
  EditorSceneManager.OpenScene("Assets/Scenes/SpatialSurvivor.unity");yield return new EnterPlayMode();yield return null;yield return null;var game=Object.FindObjectOfType<SurvivorGame>();for(int i=0;i<10&&!game.Ready;i++)yield return null;Assert.That(game.Ready,Is.True);game.enabled=false;game.StartRun();game.player.elapsed=480;game.player.health=game.player.maxHealth=1000000;game.player.damage=0;System.Array.Clear(game.player.stacks,0,game.player.stacks.Length);var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(SurvivorGame).GetField("completedBosses",flags).SetValue(game,2);var wave=(SurvivorGame.Enemy[])typeof(SurvivorGame).GetField("enemies",flags).GetValue(game);var spawn=typeof(SurvivorGame).GetMethod("Spawn",flags);for(int i=0;i<18;i++)Assert.That((bool)spawn.Invoke(game,new object[]{wave[i],wave[i].type}),Is.True,"Spawn "+i);typeof(SurvivorGame).GetField("spawn",flags).SetValue(game,100f);
  var expectedScale=new[]{.32f,.33f,.515f,.36f,1.075f,.32f,.4f,.37f,.38f,.43f,.39f};var expectedRadius=new[]{.1f,.1f,.21f,.135f,.475f,.14f,.18f,.15f,.15f,.21f,.16f};foreach(var e in wave){Assert.That(e.baseScale.x,Is.EqualTo(expectedScale[e.type]).Within(.0001f));Assert.That(e.radius,Is.EqualTo(expectedRadius[e.type]).Within(.0001f));}
  for(int f=0;f<900;f++)game.Step(1/90f);var travel=new float[18];for(int f=0;f<180;f++){var before=new Vector3[18];for(int i=0;i<18;i++)before[i]=wave[i].go.transform.position;game.Step(1/90f);for(int i=0;i<18;i++)travel[i]+=SurvivorGame.Distance(before[i],wave[i].go.transform.position);}
  for(int i=0;i<18;i++){Assert.That(travel[i],Is.GreaterThan(.2f),"Live wave must keep moving: "+i);Assert.That(wave[i].active&&!wave[i].falling,Is.True);Assert.That(game.platform.Navigation.Contains(wave[i].go.transform.position,wave[i].radius),Is.True);for(int j=i+1;j<18;j++)Assert.That(SurvivorGame.Distance(wave[i].go.transform.position,wave[j].go.transform.position),Is.GreaterThanOrEqualTo(SurvivorEnemyCrowd.Radius(wave[i])+SurvivorEnemyCrowd.Radius(wave[j])+.02f),"Combat pair "+i+" / "+j);}Assert.That(game.player.health,Is.LessThan(1000000),"Circling creatures must still attack");float clock=game.player.elapsed;var pos=wave[0].go.transform.position;game.Pause();game.Step(1);Assert.That(wave[0].go.transform.position,Is.EqualTo(pos));Assert.That(game.player.elapsed,Is.EqualTo(clock));yield return new ExitPlayMode();
 }
 [Test]public void PausedResolverDoesNotMoveAnOverlap(){At(0,Vector3.zero);At(1,Vector3.zero);SurvivorEnemyCrowd.Resolve(crowd,nav,0);Assert.That(crowd[0].go.transform.position,Is.EqualTo(center));Assert.That(crowd[1].go.transform.position,Is.EqualTo(center));}
}
}
